import {quests,pondModel,questExperimentValid,foodEdges} from './quest-science.js';
import {teachingDNA,analyzeDNA,aminoAcids} from './studio-science.js';
import {escapeHTML as esc} from './learning.js';
import {markActivity} from './journey-data.js';
const nodeNames={plant:'Cây xanh',rabbit:'Thỏ',snake:'Rắn',hawk:'Chim ăn thịt',decomposer:'Vi sinh vật phân giải'},nodePoints={plant:[13,48],rabbit:[38,20],snake:[63,20],hawk:[87,48],decomposer:[50,82]};
export function createBioQuests(root,api){
 let selected='pond',fromNode='';const sessions=Object.fromEntries(quests.map(q=>[q.id,{stage:0,hypothesis:'',nutrients:90,plants:25,connectivity:15,dna:teachingDNA,edges:[],factor:'',control:''}]));
 root.innerHTML=`<header class="campus-heading"><div><span class="eyebrow">BIOQUEST / VẬN DỤNG ĐỂ HIỂU</span><h1 data-page-heading tabindex="-1">Một câu chuyện.<br><em>Bạn là người khám phá.</em></h1><p>Thu thập bằng chứng, thử một giả thuyết và giải thích lựa chọn. Mỗi nhiệm vụ mới mở một huy hiệu và 40 XP.</p></div><a class="campus-link" href="#/journey">Hành trình của tôi ↗</a></header><div class="quest-picker" role="group" aria-label="Chọn nhiệm vụ BioQuest">${quests.map((q,i)=>`<button type="button" data-quest="${q.id}"><span>0${i+1}</span><strong>${q.title}</strong><small>${q.tag}</small><b data-quest-check="${q.id}"></b></button>`).join('')}</div><div class="quest-workspace"><aside class="quest-story"><span class="campus-kicker" id="quest-tag"></span><h2 id="quest-title"></h2><p id="quest-story"></p><div class="quest-evidence"><span>BỘ HỒ SƠ CỦA BẠN</span><p id="quest-evidence"></p></div><a id="quest-source" class="campus-link" target="_blank" rel="noopener">Đọc nguồn khoa học ↗</a><p class="campus-small">Bối cảnh và dữ liệu trong nhiệm vụ do VNScape biên soạn, không phải báo cáo của một địa phương hoặc ca bệnh thật.</p></aside><section class="quest-action"><ol class="quest-stepper"><li data-quest-step="0">01 · Giả thuyết</li><li data-quest-step="1">02 · Thử & đối chiếu</li><li data-quest-step="2">03 · Giải thích</li></ol><div id="quest-start"><label for="quest-hypothesis">Bạn nghĩ điều gì đang xảy ra? Cần bằng chứng nào?</label><textarea id="quest-hypothesis" rows="3" maxlength="1200" placeholder="Tôi dự đoán… Tôi muốn so sánh…"></textarea><button type="button" class="campus-button" id="quest-begin">Mang giả thuyết vào mô hình →</button></div><div id="quest-experiment" hidden><div id="quest-scene" class="quest-scene"></div><div id="quest-controls" class="quest-controls"></div><button type="button" class="campus-button" id="quest-verify">Đối chiếu phương án</button></div><div id="quest-reasoning" hidden><h3 id="quest-question"></h3><div id="quest-answers" class="campus-answers"></div></div><div id="quest-finished" hidden><span class="quest-earned" aria-hidden="true">✳</span><h3>Một khám phá đã có bằng chứng.</h3><p id="quest-reward"></p><button type="button" class="campus-button" id="quest-save">Lưu báo cáo vào sổ tay</button><button type="button" class="campus-button secondary" id="quest-replay">Khám phá lại</button><a href="#/journey" class="campus-link">Xem hành trình →</a></div><p class="quest-feedback" id="quest-feedback" role="status"></p></section></div>`;
 const current=()=>sessions[selected];
 function drawFoodEdges(){const web=root.querySelector('.quest-food-web');if(!web||web.clientWidth===0)return;const r=web.getBoundingClientRect(),svg=web.querySelector('svg');svg.setAttribute('viewBox','0 0 '+r.width+' '+r.height);for(const path of svg.querySelectorAll('[data-food-edge]')){const [a,b]=path.dataset.foodEdge.split('>'),ar=web.querySelector('[data-food-node="'+a+'"]').getBoundingClientRect(),br=web.querySelector('[data-food-node="'+b+'"]').getBoundingClientRect(),ax=ar.x+ar.width/2-r.x,ay=ar.y+ar.height/2-r.y,bx=br.x+br.width/2-r.x,by=br.y+br.height/2-r.y,dx=bx-ax,dy=by-ay,start=Math.min((ar.width/2+4)/Math.abs(dx||.001),(ar.height/2+4)/Math.abs(dy||.001)),end=Math.min((br.width/2+6)/Math.abs(dx||.001),(br.height/2+6)/Math.abs(dy||.001));path.setAttribute('d','M'+(ax+dx*start)+' '+(ay+dy*start)+'L'+(bx-dx*end)+' '+(by-dy*end))}}
 const foodResize=new ResizeObserver(drawFoodEdges);foodResize.observe(root.querySelector('#quest-scene'));
 function scene(){const s=current(),q=quests.find(q=>q.id===selected),stage=root.querySelector('#quest-scene');
 if(selected==='pond'){const m=pondModel(s.nutrients,s.plants);stage.innerHTML=`<svg viewBox="0 0 650 300" role="img" aria-label="Ao minh họa theo điều kiện dinh dưỡng"><defs><linearGradient id="pond-water" x2="0" y2="1"><stop stop-color="#b5d4bc"/><stop offset="1" stop-color="#6d9b8b"/></linearGradient></defs><path d="M0 45q190 30 340 0t310 0v255H0Z" fill="url(#pond-water)"/><path d="M0 45q180 35 330 0t320 0" fill="none" stroke="#e9eed0" stroke-width="5"/>${Array.from({length:Math.ceil(m.algae/4)},(_,i)=>`<ellipse cx="${20+(i*71)%610}" cy="${65+i%3*8}" rx="18" ry="4" fill="#8caa60" opacity=".65"/>`).join('')}${Array.from({length:Math.ceil(s.plants/10)},(_,i)=>`<path d="M${20+i*59} 300q-20-60 3-90m-3 55-15-21m16 8 16-26" stroke="#71985e" stroke-width="5" fill="none"/>`).join('')}<g class="quest-fish"><path d="M255 165q42-33 84 0-42 32-84 0l-23-19v37Z" fill="#ede0ad"/><circle cx="325" cy="161" r="3" fill="#46664c"/></g></svg><div class="quest-readings"><span>Dinh dưỡng <b>${m.nutrients}</b></span><span>Oxygen quy ước <b>${m.oxygen}</b></span></div>`}
 else if(selected==='corridor')stage.innerHTML=`<div class="corridor-model" style="--connection:${s.connectivity}%"><span class="forest-fragment">♣<small>Sinh cảnh A</small></span><span class="forest-corridor"></span><span class="forest-fragment">♣<small>Sinh cảnh B</small></span><i class="corridor-animal">●</i></div><div class="quest-readings"><span>Kết nối giả định <b>${s.connectivity}%</b></span></div>`;
 else if(selected==='code'){const r=analyzeDNA(s.dna);stage.innerHTML=`<div class="quest-code-model"><span>MẠCH MÃ HÓA DNA · 5′ → 3′</span><code>${esc(s.dna)}</code><span>mRNA · 5′ → 3′</span><code>${r.valid?r.mrna:'Trình tự chưa hợp lệ'}</code><span>CHUỖI AMINO ACID</span><strong>${r.valid&&r.starts?r.protein.map(a=>aminoAcids[a][0]).join(' — '):'Chưa dịch được trong khung đã chọn'}</strong></div>`}
 else if(selected==='web'){stage.innerHTML=`<div class="quest-food-web"><svg viewBox="0 0 600 360" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="food-arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0 7 3 0 6Z" fill="#6c9065"/></marker></defs>${s.edges.map(edge=>{const [a,b]=edge.split('>'),p=nodePoints[a],v=nodePoints[b];return `<path data-food-edge="${edge}" d="M${p[0]*6} ${p[1]*3.6}L${v[0]*6} ${v[1]*3.6}" fill="none" stroke="#7a9c70" stroke-width="2" marker-end="url(#food-arrow)"/>`}).join('')}</svg>${Object.entries(nodeNames).map(([id,label])=>`<button type="button" data-food-node="${id}" aria-pressed="${id===fromNode}" style="left:${nodePoints[id][0]}%;top:${nodePoints[id][1]}%"><span>${id==='plant'?'✳':id==='decomposer'?'◌':'◈'}</span>${label}</button>`).join('')}</div>`}
 else stage.innerHTML=`<div class="quest-data-table"><span>DỮ LIỆU HOÀN TOÀN GIẢ ĐỊNH</span><table><thead><tr><th>Nhóm</th><th>Ghi nhận</th><th>Không ghi nhận</th></tr></thead><tbody><tr><td>Nguồn nước A</td><td>8</td><td>4</td></tr><tr><td>Nguồn nước B</td><td>1</td><td>11</td></tr></tbody></table><p>Hai nhóm cùng thực đơn. Quan sát sự khác biệt để đề xuất hướng điều tra; chưa được kết luận nguyên nhân.</p></div>`;
 if(selected==='web')root.querySelector('#food-edge-list').innerHTML=s.edges.map(edge=>`<button type="button" data-remove-edge="${edge}" aria-label="Xóa nối ${nodeNames[edge.split('>')[0]]} đến ${nodeNames[edge.split('>')[1]]}">${nodeNames[edge.split('>')[0]]} → ${nodeNames[edge.split('>')[1]]} ×</button>`).join('');
 drawFoodEdges();
 }
 function controls(){const s=current(),target=root.querySelector('#quest-controls');
 if(selected==='pond')target.innerHTML=`<label>Đầu vào dinh dưỡng <output id="quest-nutrients-value">${s.nutrients}</output><input id="quest-nutrients" data-quest-control="nutrients" type="range" min="0" max="100" value="${s.nutrients}"></label><label>Thực vật thủy sinh quy ước <input id="quest-plants" data-quest-control="plants" type="range" min="0" max="100" value="${s.plants}"></label><p class="campus-small">Mục tiêu trong mô hình: đầu vào dinh dưỡng ≤30 và chỉ số oxygen ≥60. Chỉ số không có đơn vị mg/L. Giữ một biến, đổi biến còn lại để so sánh.</p>`;
 else if(selected==='corridor')target.innerHTML=`<label>Thiết kế mức kết nối sinh cảnh <output id="quest-connectivity-value">${s.connectivity}%</output><input id="quest-connectivity" data-quest-control="connectivity" type="range" min="0" max="100" value="${s.connectivity}"></label><p class="campus-small">Đưa kết nối lên ít nhất 65% trong sơ đồ. Con số là mục tiêu trò chơi, không phải ngưỡng bảo tồn ngoài thực địa. Sơ đồ không dự báo số cá thể.</p>`;
 else if(selected==='code')target.innerHTML=`<label for="quest-dna">Chỉnh bộ ba GAA ở vị trí 4–6</label><input id="quest-dna" data-quest-control="dna" maxlength="90" spellcheck="false" value="${s.dna}"><details><summary>Một gợi ý từ bảng mã</summary><p>GAA và GAG cùng mã hóa glutamate trong bảng mã chuẩn. Chỉ đổi vị trí 6.</p></details>`;
 else if(selected==='web')target.innerHTML=`<p>Chọn sinh vật làm nguồn thức ăn, rồi chọn bên nhận. Nối chuỗi cây → thỏ → rắn → chim; nối từng nhóm tới vi sinh vật phân giải.</p><div id="food-edge-list" class="food-edge-list"></div><p class="campus-small">Bấm × để xóa nối. Mũi tên minh họa hướng truyền vật chất và năng lượng; không có mũi tên hoàn trả năng lượng từ phân giải về cây.</p>`;
 else target.innerHTML=`<label for="quest-factor">Yếu tố cần kiểm tra tiếp</label><select id="quest-factor" data-quest-control="factor"><option value="">Chọn từ bằng chứng</option><option value="water">Sự khác nhau về nguồn nước</option><option value="weather">Chỉ màu áo của người tham gia</option></select><label for="quest-control">Phương án phân tích phù hợp</label><select id="quest-control" data-quest-control="control"><option value="">Chọn cách đối chiếu</option><option value="same-other">Đối chiếu nhóm, kiểm tra các yếu tố khác tương tự</option><option value="change-all">Đổi nhiều yếu tố cùng lúc rồi kết luận</option></select><p class="campus-small">Chỉ phân tích số liệu. Không thử cho người tiếp xúc một nguồn nghi gây hại.</p>`;
 }
 function render(){const q=quests.find(q=>q.id===selected),s=current();for(const [id,text] of [['quest-tag',q.tag],['quest-title',q.title],['quest-story',q.story],['quest-evidence',q.evidence],['quest-question',q.question]])root.querySelector('#'+id).textContent=text;root.querySelector('#quest-source').href=q.source;root.querySelector('#quest-hypothesis').value=s.hypothesis;
 for(const [id,stage] of [['quest-start',0],['quest-experiment',1],['quest-reasoning',2],['quest-finished',3]])root.querySelector('#'+id).hidden=s.stage!==stage;root.querySelectorAll('[data-quest-step]').forEach(b=>b.classList.toggle('done',Number(b.dataset.questStep)<=s.stage));root.querySelectorAll('[data-quest]').forEach(b=>{const chosen=b.dataset.quest===selected;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen));b.querySelector('b').textContent=api.getState().completedQuests.includes(b.dataset.quest)?'✓':''});root.querySelector('#quest-feedback').textContent='';root.querySelector('#quest-answers').innerHTML=q.answers.map((a,i)=>`<button type="button" data-quest-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${a}</button>`).join('');controls();scene()}
 root.addEventListener('input',e=>{const key=e.target.dataset.questControl;if(key){current()[key]=e.target.type==='range'?Number(e.target.value):e.target.value;scene();const out=root.querySelector('#quest-'+key+'-value');if(out)out.textContent=current()[key]+(key==='connectivity'?'%':'')}if(e.target.id==='quest-hypothesis')current().hypothesis=e.target.value});
 root.addEventListener('change',e=>{if(e.target.dataset.questControl)current()[e.target.dataset.questControl]=e.target.value});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const s=current(),q=quests.find(q=>q.id===selected);
 if(b.dataset.quest){selected=b.dataset.quest;fromNode='';render()}
 else if(b.id==='quest-begin'){if(s.hypothesis.trim().length<8){root.querySelector('#quest-feedback').textContent='Viết một dự đoán hoặc một điều muốn so sánh trước khi thử.';return}s.stage=1;render()}
 else if(b.id==='quest-verify'){if(questExperimentValid(selected,s)){s.stage=2;render()}else{root.querySelector('#quest-feedback').textContent='Phương án chưa thỏa các điều kiện được nêu. Xem lại bằng chứng và chỉ đổi một yếu tố mỗi lần.';api.feedback?.(b,false)}}
 else if(b.dataset.foodNode){const id=b.dataset.foodNode;if(!fromNode)fromNode=id;else{if(fromNode!==id){const edge=fromNode+'>'+id;if(!s.edges.includes(edge))s.edges.push(edge)}fromNode=''}scene()}
 else if(b.dataset.removeEdge){s.edges=s.edges.filter(edge=>edge!==b.dataset.removeEdge);scene()}
 else if(b.dataset.questAnswer!==undefined){const correct=Number(b.dataset.questAnswer)===q.correct;api.feedback?.(b,correct);root.querySelector('#quest-feedback').textContent=correct?q.explanation:'Chưa đủ căn cứ. Hãy phân biệt điều quan sát được, kết quả mô hình và kết luận về thế giới thật.';if(correct){s.stage=3;const state=api.getState(),first=!state.completedQuests.includes(selected);if(first)state.completedQuests.push(selected);markActivity(state);api.persist();render();root.querySelector('#quest-feedback').textContent=q.explanation;root.querySelector('#quest-reward').textContent=`Huy hiệu: ${q.badge}. ${first?'+40 XP ở lần hoàn thành đầu tiên.':'Bạn đã ôn lại nhiệm vụ; XP không cộng lặp.'}`}}
 else if(b.id==='quest-replay'){s.stage=0;render()}
 else if(b.id==='quest-save'){api.addNote(`BioQuest: ${q.title}`,`Giả thuyết của tôi:\n${s.hypothesis}\n\nBằng chứng giả định:\n${q.evidence}\n\nPhương án đã đối chiếu:\n${selected==='web'?s.edges.map(edge=>edge.split('>').map(n=>nodeNames[n]).join(' → ')).join('\n'):selected==='code'?s.dna:selected==='pond'?`Dinh dưỡng ${s.nutrients}; thực vật ${s.plants}; oxygen quy ước ${pondModel(s.nutrients,s.plants).oxygen}`:selected==='corridor'?`Kết nối giả định ${s.connectivity}%`:'So sánh nguồn nước; xem xét yếu tố gây nhiễu.'}\n\nGiải thích:\n${q.explanation}\n\nNguồn: ${q.source}\nTình huống do VNScape biên soạn, không phải số đo thực.`);api.toast('Đã giữ báo cáo BioQuest trong sổ tay.')}
 });render();return {setActive(value){if(value)render()}};
}
